#!/usr/bin/env python3
"""Check the final includes lost at the safe threshold against the review's own reference list. No model calls.

  label_check.py            writes external/label-check.md

For every CLEF TAR condition, each finally included record scored below 0.06 is looked up in the reference list of
the Cochrane review it belongs to (Europe PMC references of the review version used for the criteria). As a control,
the same is done for all final includes of that review. A lost include that the review never cites, when the other
includes are cited, points to a labelling error. The pre-specified verdicts are not changed by this check."""
import json
import sys
import urllib.request
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import clef
import common

HERE = Path(__file__).resolve().parent
OUT = HERE / "label-check.md"
SAFE = json.loads(common.CALIBRATION.read_text())["targets"]["100%"]["threshold"]
EPMC = "https://www.ebi.ac.uk/europepmc/webservices/rest/MED/{}/references?format=json&pageSize=1000"
EFETCH = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pubmed&rettype=abstract&retmode=text&id={}"


def cited(review_pmid: str) -> set[str]:
    with urllib.request.urlopen(urllib.request.Request(EPMC.format(review_pmid), headers={"User-Agent": "sievesafe-benchmark"}), timeout=60) as r:
        refs = json.load(r).get("referenceList", {}).get("reference", [])
    return {x["id"] for x in refs if x.get("id")}


def citation(pmid: str) -> str:
    with urllib.request.urlopen(EFETCH.format(pmid), timeout=60) as r:
        first = r.read().decode(errors="replace").strip().split("\n\n")[0]
    return " ".join(first.split())[:120]


L = ["# Label check of the final includes lost at the safe threshold", "",
     "Generated by `benchmark/external/label_check.py`. The pre-specified verdicts in `results*.md` stand as they are.", ""]
checked = 0
for condition, spec in clef.CONDITIONS.items():
    info = clef.reviews(condition)
    for topic, meta in info["reviews"].items():
        scores = common.answers(spec["variant"], topic)
        rows = clef.rows(topic, meta, condition)
        includes = [r["pmid"] for r in rows if r["y"] == "1"]
        lost = [r["pmid"] for r in rows if r["y"] == "1" and r["abstract"] and scores.get(r["pmid"], 1.0) < SAFE]
        if not lost:
            continue
        refs = cited(meta["review_pmid"])
        checked += 1
        L += [f"## {topic} ({condition}): {meta['title']}", "",
              f"- Review version used: {meta['doi']} (PMID {meta['review_pmid']}), {len(refs)} references listed in Europe PMC",
              f"- Final includes cited by the review: {sum(p in refs for p in includes)} of {len(includes)}"]
        for p in lost:
            L.append(f"- Lost include PMID {p} (score {scores[p]}): {'cited' if p in refs else 'NOT cited'} by the review — {citation(p)}")
        uncited = [p for p in includes if p not in refs]
        L += [f"- Final includes not cited by the review: {', '.join(uncited) if uncited else 'none'}", ""]
if not checked:
    L += ["No final include fell below the threshold in any condition.", ""]
OUT.write_text("\n".join(L))
print(f"wrote {OUT.relative_to(common.HERE.parent)}")
